    { id: "Animal #7",  alive: [1,1,1,1], detected: [1,0,0,1] },
    { id: "Animal #12", alive: [1,1,0,0], detected: [1,1,0,0] },
    { id: "Animal #3",  alive: [1,1,1,1], detected: [1,0,1,0] },
    { id: "Animal #19", alive: [1,0,0,0], detected: [1,0,0,0] }
  ];

  let ai = 0, occ = 0, guesses = [], phase = "playing";

  const el = document.createElement("div");
  el.style.cssText = "background:#161610;border-radius:8px;padding:20px;color:#c9c0a6;font-family:sans-serif";

  function draw() {
    const a = animals[ai];
    const n = a.alive.length;

    let tiles = `&lt;div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px"&gt;`;
