    el.querySelector("#dBtn")?.addEventListener("click",  () =&gt; { guesses[occ]="d";  occ++; draw(); });
    el.querySelector("#hBtn")?.addEventListener("click",  () =&gt; { guesses[occ]="h";  occ++; draw(); });
    el.querySelector("#revBtn")?.addEventListener("click",() =&gt; { phase="revealed"; draw(); });
